<article class="path-card"><?php require ROOT.'/app/Views/components/path-art.php'; ?><div class="path-card-body"><span class="card-eyebrow"><?= e($path['category']) ?></span><h3><a href="<?= e(route_url('/paths/' . ($path['slug']))) ?>"><?= e($path['title']) ?></a></h3><p><?= e($path['description']) ?></p><div class="path-card-meta"><span><?= icon('book',15) ?> <?= (int)$path['lesson_count'] ?> lessons</span><span><?= icon('clock',15) ?> <?= (int)$path['duration_minutes'] ?> min estimated</span></div><?php if(!empty($path['enrolled'])): ?><div class="course-progress-label"><span><?= (int)$path['completed'] ?> lessons completed</span><strong><?= (int)$path['progress'] ?>%</strong></div><div class="progress-track"><span style="width:<?= (int)$path['progress'] ?>%"></span></div><?php endif; ?><a class="path-card-link" href="<?= e(route_url('/paths/' . ($path['slug']))) ?>"><?= !empty($path['enrolled'])?'Continue your journey':'Explore this path' ?> <?= icon('arrow-up-right',18) ?></a></div></article>
